function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function visit(nodes, prefix, lines) {
  for (let i = nodes.length - 1; i >= 0; i -= 1) {
    if (!Object.prototype.hasOwnProperty.call(nodes, i)) {
      throw new TypeError('fault arrays must not be sparse');
    }
    const node = nodes[i];
    if (!isPlainObject(node) || typeof node.code !== 'string' || node.code.length === 0 ||
        typeof node.note !== 'string' || node.note.length === 0) {
      throw new TypeError('invalid fault node');
    }
    if ('children' in node && !Array.isArray(node.children)) {
      throw new TypeError('children must be an array');
    }

    const path = prefix ? `${prefix}.${i + 1}` : String(i + 1);
    lines.push(`${path}: ${node.note} [${node.code}]`);
    if (node.children) visit(node.children, path, lines);
  }
}

function renderFaultTree(faults) {
  if (!Array.isArray(faults)) throw new TypeError('faults must be an array');
  const lines = [];
  visit(faults, '', lines);
  return lines.join('\n');
}

module.exports = { renderFaultTree };

