'use strict';
const assert = require('node:assert');
const api = require('./solution');

assert.strictEqual(Reflect.ownKeys(api).length, 1);
assert.strictEqual(typeof api.renderFaultTree, 'function');
const { renderFaultTree } = api;
const typeError = (fn) => assert.throws(fn, TypeError);

assert.strictEqual(renderFaultTree([]), '');

const faults = [
  { code: 'ROOT_A', note: 'First fault', extra: 10 },
  {
    code: 'ROOT_B',
    note: 'Second fault',
    children: [
      { code: 'B1', note: 'First child' },
      {
        code: 'B2',
        note: 'Second child',
        children: [{ code: 'B21', note: 'Grandchild' }]
      }
    ]
  },
  { code: 'ROOT_C', note: 'Third fault', children: [] }
];
const before = JSON.stringify(faults);
assert.strictEqual(
  renderFaultTree(faults),
  '1: First fault [ROOT_A]\n' +
  '2: Second fault [ROOT_B]\n' +
  '2.1: First child [B1]\n' +
  '2.2: Second child [B2]\n' +
  '2.2.1: Grandchild [B21]\n' +
  '3: Third fault [ROOT_C]'
);
assert.strictEqual(JSON.stringify(faults), before);

const nullPrototypeNode = Object.create(null);
nullPrototypeNode.code = 'N';
nullPrototypeNode.note = 'Null prototype';
assert.strictEqual(renderFaultTree([nullPrototypeNode]), '1: Null prototype [N]');

for (const invalid of [null, {}, 'faults', 1]) typeError(() => renderFaultTree(invalid));
for (const node of [
  null,
  [],
  new Date(),
  Object.create({ code: 'X', note: 'Y' }),
  { code: '', note: 'note' },
  { code: 'C', note: '' },
  { code: 1, note: 'note' },
  { code: 'C', note: 2 },
  { code: 'C', note: 'note', children: null },
  { code: 'C', note: 'note', children: {} }
]) {
  typeError(() => renderFaultTree([node]));
}

const sparseRoot = new Array(1);
typeError(() => renderFaultTree(sparseRoot));
const sparseChildren = new Array(2);
sparseChildren[1] = { code: 'C', note: 'child' };
typeError(() => renderFaultTree([{ code: 'P', note: 'parent', children: sparseChildren }]));
typeError(() => renderFaultTree([{ code: 'P', note: 'parent', children: [{ code: '', note: 'bad' }] }]));

